import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public final class ClaimDuplicateDetector {

    public record Claim(String id, String policyNumber, LocalDate incidentDate, BigDecimal amount) {
    }

    public record DuplicateGroup(String policyNumber, LocalDate incidentDate, BigDecimal amount, List<String> claimIds) {
    }

    private ClaimDuplicateDetector() {
    }

    public static List<List<String>> findDuplicates(List<Claim> claims) {
        List<List<String>> groups = new ArrayList<>();
        for (DuplicateGroup group : findDuplicateGroups(claims)) {
            groups.add(group.claimIds());
        }
        return groups;
    }

    public static List<DuplicateGroup> findDuplicateGroups(List<Claim> claims) {
        if (claims == null) {
            return List.of();
        }
        Map<String, List<Claim>> grouped = new TreeMap<>();
        for (Claim claim : claims) {
            if (claim == null || blank(claim.id()) || blank(claim.policyNumber())
                    || claim.incidentDate() == null || claim.amount() == null) {
                continue;
            }
            String key = claim.policyNumber().trim().toUpperCase() + "|" + claim.incidentDate()
                    + "|" + claim.amount().stripTrailingZeros().toPlainString();
            grouped.computeIfAbsent(key, ignored -> new ArrayList<>()).add(claim);
        }
        List<DuplicateGroup> groups = new ArrayList<>();
        for (List<Claim> bucket : grouped.values()) {
            if (bucket.size() < 2) {
                continue;
            }
            List<String> ids = new ArrayList<>();
            for (Claim claim : bucket) {
                ids.add(claim.id());
            }
            ids.sort(String::compareTo);
            Claim first = bucket.get(0);
            groups.add(new DuplicateGroup(
                    first.policyNumber().trim().toUpperCase(),
                    first.incidentDate(),
                    first.amount().stripTrailingZeros(),
                    List.copyOf(ids)));
        }
        groups.sort((left, right) -> left.claimIds().get(0).compareTo(right.claimIds().get(0)));
        return groups;
    }

    private static boolean blank(String value) {
        return value == null || value.trim().isEmpty();
    }
}
